import mpmath as mp
mp.mp.dps=50

def f(n,a):
    z=4*a/(1+a)**2
    return (1+a)**(n-1)*mp.hyper2f1((1-n)/2,1-n/2,2,z)

def g_series(a, N=200):
    x=a/(1+a)**2
    # S=sum C_k H_{2k} x"'^k with sign negative; g=ln(1+a)-G/(1+a)
    s=mp.mpf('"'0')
    for k in range(1,N):
        C=mp.binomial(2*k,k)/(k+1)
        H=mp.harmonic(2*k)
        s += C*H*x**k
    return mp.log(1+a)-s/(1+a)

def g_int(a):
    if a==0: return mp.mpf('0')
    z=4*a/(1+a)**2
    # F'(0)=1/2 integral, gamma prefactor derivative zero
    J=mp.quad(lambda t: (1-z*t)**(-mp.mpf('0.5'))*mp.log((1-t)*(1-z*t)/t), [0,1])
    return mp.log(1+a)+J/(2*(1+a))

def g_formula(a):
    if a==0: return mp.mpf('0')
    return -1-((1-a)/a)*mp.log(1-a)
for a in [mp.mpf('0.001'), mp.mpf('0.1'), mp.mpf('0.25'), mp.mpf('0.5'), mp.mpf('0.9'), mp.mpf('0.999'), mp.mpf('1')]:
