from functools import lru_cache

def catalan(n):
    from math import comb
    return comb(2*n,n)//(n+1)

# recursively generate noncrossing set partitions as frozensets of blocks
@lru_cache(None)
def nc_partitions_tuple(elements):
    els=tuple(elements)
    if not els:
        return ((),)
    first=els[0]
    out=[]
    # choose block containing first as els[0], els[i1], ...; remaining elements split into independent intervals
    # subset represented by selected indices after first
    for mask in range(1<<(len(els)-1)):
        block=[first]
        selected=[]
        unselected=[]
        for j,x in enumerate(els[1:]):
            if mask>>j & 1:
                block.append(x); selected.append(x)
            else:
                unselected.append(x)
        # Block must not interleave with others: all unselected split into gaps around selected elements.
        # A set partition extending this block is noncrossing iff each connected interval between
        # consecutive selected cyclic points is independently partitioned; no crossing block spanning gaps.
        # Elements in gaps: after first before sel1, between sels, after last selected (which is same outer cyclic gap before first?)
        # Since first fixes cyclic boundary, valid unselected runs between consecutive block elements in linear order,
        # including after last (which is same cyclic gap before first), cannot combine across selected. Runs before first none.
        boundaries=[first]+selected
        runs=[]
        for a,b in zip(boundaries,boundaries[1:]):
            runs.append(tuple(x for x in els if a<x<b))
        runs.append(tuple(x for x in els if x>boundaries[-1]))
        # generate product partitions of runs
        parts=[()]
        ok=True
        for run in runs:
            ps=nc_partitions_tuple(run)
            parts=[p+q for p in parts for q in ps]
        out.extend(tuple(sorted((tuple(sorted(block)),)+p)) for p in parts)
    return tuple(set(out))

def nc_partitions(n):
    return [frozenset(frozenset(b) for b in p) for p in nc_partitions_tuple(tuple(range(1,n+1)))]

def refine(A,D):
    # every A block subset of a D block
    return all(any(a<=d for d in D) for a in A)

def interval_size_lower(A):
    prod=1
    for a in A: prod*=catalan(len(a))
    return prod

def interval_size_pair(A,D):
    prod=1
    for d in D:
        k=sum(1 for a in A if a<=d)
        prod*=catalan(k)
    return prod

def count(n):
    N=nc_partitions(n)
    total=0
    weighted_pairs=0
    for A in N:
        lower=interval_size_lower(A)
        for D in N:
            if refine(A,D):
                mid=interval_size_pair(A,D)
                upper=catalan(len(D))
                total += lower*mid*mid*upper
                weighted_pairs += 1
    return total, len(N), weighted_pairs
for n in range(1,9):
    print(n, count(n))
