def catalan(n): return comb(2*n,n)//(n+1)
@lru_cache(None)
def ncparts(els):
 els=tuple(els)
 if not els: return ((),)
 first=els[0]; out=[]
 for mask in range(1<<(len(els)-1)):
  selected=[x for j,x in enumerate(els[1:]) if mask>>j&1]
  orbits=[first]+selected
  runs=[]
  for a,b in zip(orbits,orbits[1:]): runs.append(tuple(x for x in els if a<x<b))
  runs.append(tuple(x for x in els if x>orbits[-1]))
  ps=[()]
  for run in runs: ps=[p+q for p in ps for q in ncparts(run)]
  out.extend(tuple(sorted((tuple(sorted((first,)+tuple(selected))),)+p)) for p in ps)
 return tuple(set(out))
def direct_weight(n):
 total=0
 for A in ncparts(tuple(range(n))):
  aw=catalan(len(A))
  for D in ncparts(tuple(range(n))):
   if all(any(set(a)<=set(d) for d in D) for a in A):
    total += aw*catalan(len(D))**2
 return total
for n in range(1,9): print(n,direct_weight(n))
