from functools import lru_cache
from math import comb

def catalan(n): return comb(2*n,n)//(n+1)
@lru_cache(None)
def ncparts(els):
 els=tuple(els)
 if not els: return ((),)
 first=els[0]; out=[]
 for mask in range(1<<(len(els)-1)):
  selected=[x for j,x in enumerate(els[1:]) if mask>>j&1]
  boundaries=[first]+selected
  runs=[]
  for a,b in zip(boundaries,boundaries[1:]): runs.append(tuple(x for x in els if a<x<b))
  runs.append(tuple(x for x in els if x>boundaries[-1]))
  ps=[()]
  for run in runs: ps=[p+q for p in ps for q in ncparts(run)]
  out.extend(tuple(sorted((tuple(sorted((first,)+tuple(selected))),)+p)) for p in ps)
 return tuple(set(out))
def type_weight(n):
 total=0
 for A in ncparts(tuple(range(n))):
  lower=catalan(len(A))
  # number B in [hat0,A] = prod C(|block|)
  lowint=1
  for b in A: lowint*=catalan(len(b))
  # for each D >= A, weights upper C(|D|), and middle squared interval
  for D in ncparts(tuple(range(n))):
   if all(any(set(a)<=set(d) for d in D) for a in A):
    mid=1
    for d in D:
     k=sum(1 for a in A if set(a)<=set(d))
     mid*=catalan(k)
    total += lower*lowint*mid*mid*catalan(len(D))
 return total
for n in range(1,8): print(n,type_weight(n),flush=True)
