from functools import lru_cache
from math import comb

def catalan(n): return comb(2*n,n)//(n+1)
# Generate NC partitions of list represented by tuple. Return list of partitions, each tuple of blocks (tuples).
@lru_cache(None)
def nc(els):
    els=tuple(els)
    if not els: return ((),)
    first=els[0]
    out=[]
    # first block contains first and selected later elements
    for mask in range(1<<(len(els)-1)):
        selected=tuple(x for j,x in enumerate(els[1:]) if mask>>j&1)
        block=(first,)+selected
        boundaries=block
        runs=[]
        for a,b in zip(boundaries,boundaries[1:]):
            runs.append(tuple(x for x in els if a<x<b))
        runs.append(tuple(x for x in els if x>boundaries[-1]))
        parts=[()]
        for run in runs:
            ps=nc(run)
            parts=[p+q for p in parts for q in ps]
        for p in parts:
            out.append((block,)+p)
    return tuple(out)

@lru_cache(None)
def H(n):
    return sum(catalan(len(D))**2 for D in nc(tuple(range(n))))

@lru_cache(None)
def S(n):
    total=0
    for A in nc(tuple(range(n))):
        prod=1
        for b in A: prod*=H(len(b))
        total += catalan(len(A))*prod
    return total
for n in range(1,12): print(n,S(n),flush=True)
