# Enumerate noncrossing partitions via recursive algorithm, compute exact direct-history equivalent sum:
# total = sum_{A<=D} |[0,A]| * |[A,D]| * |[D,1]|"'^2? Try weight variants until small matches.
from functools import lru_cache
from math import comb

def C(n): return comb(2*n,n)//(n+1)
@lru_cache(None)
def nc(els):
 els=tuple(els)
 if not els: return ((),)
 first=els[0]; out=[]
 for mask in range(1<<(len(els)-1)):
  selected=tuple(x for j,x in enumerate(els[1:]) if mask>>j&1)
  block=(first,)+selected; runs=[]
  for a,b in zip(block,block[1:]): runs.append(tuple(x for x in els if a<x<b))
  runs.append(tuple(x for x in els if x>block[-1]))
  parts=[()]
  for run in runs: parts=[p+q for p in parts for q in nc(run)]
  out += [(block,)+p for p in parts]
 return tuple(out)
def interval_count(A,D):
 prod=1
 for d in D:
  k=sum(1 for a in A if set(a)<=set(d))
  prod*=C(k)
 return prod
