from scipy.sparse import csr_matrix,coo_matrix,diags
from scipy.sparse.linalg import eigsh
D=np.load('/tmp/codex-llm-wflczmbq/mesh60_good.npz');Qt=D['Qt'];Qb=D['Qb'];b1=D['b1'];b2=D['b2']
# rebuild sparse base
s=np.sqrt(3.);bm=4*np.pi/(s*(3.52/(2*np.sin(np.deg2rad(3.5)/2))));kin=7619.96423/1.2;V=16.5;ps=np.deg2rad(-105.9);w=-18.8;C=np.array([[-.5,-s/2],[s/2,-.5]]);gs=[];qs=[]
for i in range(3):gs.append(np.linalg.matrix_power(C,i)@np.array([bm,0.]));qs.append(np.linalg.matrix_power(C,i)@np.array([0,bm/s]))
Nt=len(Qt);Nb=len(Qb);dim=Nt+Nb;Qa=np.vstack([Qt,Qb]);Dmap={}
def ad(i,j,v):Dmap[(i,j)]=Dmap.get((i,j),0)+v
for i,Q in enumerate(Qb):
 for j,R in enumerate(Qb):
  d=Q-R
  for g in gs:
   if (d-g)@(d-g)<1e-12:ad(Nt+i,Nt+j,V*np.exp(-1j*ps))
   elif (d+g)@(d+g)<1e-12:ad(Nt+i,Nt+j,V*np.exp(1j*ps))
for i,Q in enumerate(Qt):
 for j,R in enumerate(Qt):
  d=Q-R
  for g in gs:
   if (d-g)@(d-g)<1e-12:ad(i,j,V*np.exp(1j*ps))
   elif (d+g)@(d+g)<1e-12:ad(i,j,V*np.exp(-1j*ps))
for i,Q in enumerate(Qt):
 for j,R in enumerate(Qb):
  d=R-Q
  for q in qs:
   if (d-q)@(d-q)<1e-12:ad(i,Nt+j,w)
r=[];c=[];v=[]
for (i,j),val in Dmap.items():r.append(i);c.append(j);v.append(val)
base=csr_matrix(coo_matrix((v,(r,c)),shape=(dim,dim)))
for L in [12,16,20,24]:
 Us=[];Es=[];t=time.time()
 for l1 in range(L):
  for l2 in range(L):
   k=(l1/L-.5)*b1+(l2/L-.5)*b2;H=base+diags(kin*np.sum((Qa-k)**2,1));e,u=eigsh(H,k=6,which='LA',tol=1e-9,maxiter=3000);o=np.argsort(e);Es.append(e[o]);Us.append(u[:,o])
 Us=np.array(Us).reshape(L,L,dim,6);Es=np.array(Es).reshape(L,L,6)
 Cs=[]
 # bands relative highest: 5 top,4 second,3 third; also 4 and 3 composite
 for band in [5,4,3]:
  u=Us[:,:,:,band];z1=np.sum(np.conjugate(u)*np.roll(u,-1,axis=0),axis=2);z2=np.sum(np.conjugate(np.roll(u,-1,axis=0))*np.roll(u,(-1,-1),axis=(0,1)),axis=2);z3=np.sum(np.conjugate(np.roll(u,(-1,-1),axis=(0,1)))*np.roll(u,-1,axis=1),axis=2);z4=np.sum(np.conjugate(np.roll(u,-1,axis=1))*u,axis=2);Cs.append(np.sum(np.angle(z1*z2*z3*z4))/(2*np.pi))
 print('L',L,'Cs top second third',Cs,'time',time.time()-t,'min gaps',*[np.min(Es[:,:,i]-Es[:,:,i-1]) for i in [5,4,3]])
